// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        uint256 ticket = 10;
        vm.assume(amount1 == ticket);
        vm.assume(amount2 == ticket);
        address player = address(0x1234);
        vm.deal(player, ticket * 2);

        vm.prank(player);
        c.play{value: amount1}();
        uint256 potAfterFirst = c.pot();

        vm.prank(player);
        c.play{value: amount2}();
        uint256 potAfterSecond = c.pot();

        assertTrue(!(potAfterSecond == 0 && potAfterFirst != 0));
    }
}
